export const title = "How to Choose a Tablet Stand That Fits Your Case and Stylus Routine";
export const metaTitle = "Tablet Stands That Fit Your Case and Stylus";
export const metaDescription = "Check tablet-and-case thickness, support lips, buttons, charging, stylus access, and the difference between viewing and writing.";
